#!/usr/bin/env bash
# constat:template id=jest-rewind-to-base version=52 sha256=946507ad0558bb18a693daff7a054c88fe56580b7b2305a352fdf89937e4e937
# Rewinds the working tree to the code as it was BEFORE this branch's change, while KEEPING the
# branch's own test files and the harness that installs and runs them. Generated by DoneMark's
# onboarding pull request; see .github/scripts/rewind-to-base.sh in the constat repository for
# the fuller explanation this is adapted from.
#
# Usage: constat-rewind-to-base.sh <base-ref>

set -euo pipefail

BASE_REF="${1:?usage: constat-rewind-to-base.sh <base-ref>}"
HEAD_SHA="$(git rev-parse HEAD)"

git fetch --no-tags origin "$BASE_REF"
MERGE_BASE="$(git merge-base FETCH_HEAD "$HEAD_SHA")"

echo "head:       $HEAD_SHA"
echo "base ref:   $BASE_REF"
echo "merge-base: $MERGE_BASE"

if [ "$MERGE_BASE" = "$HEAD_SHA" ]; then
  echo "merge-base equals HEAD — this branch changes nothing against $BASE_REF." >&2
  exit 1
fi

git checkout --quiet --detach "$MERGE_BASE"

KEEP="$(mktemp)"
trap 'rm -f "$KEEP"' EXIT
git ls-tree -r --name-only "$HEAD_SHA" >"$KEEP.all"
grep -E '\.(test|spec)\.[cm]?[jt]sx?$|(^|/)__tests__/' "$KEEP.all" >"$KEEP" || true
grep -E '(^\.github/|(^|/)package\.json$|package-lock\.json$|yarn\.lock$|pnpm-lock\.yaml$|jest\.config\.[cm]?[jt]s$|babel\.config\.[cm]?js$|(^|/)tsconfig[^/]*\.json$)' \
  "$KEEP.all" >>"$KEEP" || true
rm -f "$KEEP.all"

if [ ! -s "$KEEP" ]; then
  echo "no test files or harness files found at $HEAD_SHA — refusing to run a meaningless comparison." >&2
  exit 1
fi

sort -u "$KEEP" | tr '\n' '\0' | xargs -0 git checkout "$HEAD_SHA" --
echo "restored $(sort -u "$KEEP" | wc -l | tr -d ' ') file(s) from HEAD onto the before-code tree"
